param([string]$GameRoot='', [switch]$HubConfirmed, [switch]$NoPause)
$ErrorActionPreference='Stop';. (Join-Path $PSScriptRoot '..\Modules\OwnedModFiles.ps1');$id='obvr';$receipt=Join-Path $PSScriptRoot '.installed_path'
function Finish([int]$c){if(-not $NoPause){Read-Host 'Press Enter to exit'|Out-Null};exit $c};function Test-Root([string]$p){$p -and (Test-Path (Join-Path $p 'Oblivion.exe')) -and (Test-Path (Join-Path $p ".pcvrhub_${id}_ownership.csv"))}
if(-not(Test-Root $GameRoot) -and (Test-Path $receipt)){$GameRoot=([IO.File]::ReadAllText($receipt)).Trim().Trim('"')};if(-not(Test-Root $GameRoot)){Write-Host '  No Hub-owned OBVR installation was found.' -ForegroundColor Yellow;Finish 0};if(Get-Process -Name 'Oblivion','obse_loader' -ErrorAction SilentlyContinue){Write-Host '  [XX] Close Oblivion first.' -ForegroundColor Red;Finish 1};if(-not $HubConfirmed -and (Read-Host "Remove Hub-owned OBVR files from '$GameRoot'? Type REMOVE") -cne 'REMOVE'){Finish 0}
$r=Uninstall-OwnedModPayload -GameRoot $GameRoot -Identity $id;if($r.Preserved -eq 0){Remove-Item (Join-Path $GameRoot '.pcvrhub_version') -Force -ErrorAction SilentlyContinue;Remove-Item $receipt -Force -ErrorAction SilentlyContinue};Write-Host "  [OK] Removed $($r.Removed), restored $($r.Restored), preserved $($r.Preserved)." -ForegroundColor Green;Write-Host '  Oblivion, saves, unrelated files and the shared MenuQue dependency remain installed.' -ForegroundColor Gray;Finish 0
